The issue is likely a **unit mismatch** between `Date.now()` and the JWT's `exp` field:

- `Date.now()` returns milliseconds since Unix epoch
- JWT `exp` field is in **seconds** since Unix epoch (per JWT standard)

## The Problem
```javascript
// This is WRONG - comparing milliseconds to seconds
if (Date.now() < token.exp) {
  // Token appears valid even when expired
}
```

## The Fix
Convert to the same units before comparing:

```javascript
// Option 1: Convert Date.now() to seconds
const currentTimeInSeconds = Math.floor(Date.now() / 1000);
if (currentTimeInSeconds >= token.exp) {
  return res.status(401).json({ error: 'Token expired' });
}

// Option 2: Convert exp to milliseconds
if (Date.now() >= token.exp * 1000) {
  return res.status(401).json({ error: 'Token expired' });
}
```

## Complete Middleware Example
```javascript
const jwt = require('jsonwebtoken');

const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    const decoded = jwt.verify(token, process.env.JWT_SECRET);

    // Check expiration manually (though jwt.verify() already does this)
    const currentTimeInSeconds = Math.floor(Date.now() / 1000);
    if (currentTimeInSeconds >= decoded.exp) {
      return res.status(401).json({ error: 'Token expired' });
    }

    req.user = decoded;
    next();
  } catch (error) {
    return res.status(401).json({ error: 'Invalid token' });
  }
};
```

## Better Approach
Actually, `jwt.verify()` automatically checks expiration, so you might not need manual checking:

```javascript
const authMiddleware = (req, res, next) => {
  const token = req.headers.authorization?.split(' ')[1];

  if (!token) {
    return res.status(401).json({ error: 'No token provided' });
  }

  try {
    // This will throw an error if token is expired
    const decoded = jwt.verify(token, process.env.JWT_SECRET);
    req.user = decoded;
    next();
  } catch (error) {
    if (error.name === 'TokenExpiredError') {
      return res.status(401).json({ error: 'Token expired' });
    }
    return res.status(401).json({ error: 'Invalid token' });
  }
};
```

The key fix is ensuring both timestamps use the same units (seconds or milliseconds).

I'll show you how to set up a robust PostgreSQL connection pool in Node.js using the `pg` library with proper configuration for timeouts and error handling.

## Installation

First, install the required package:

```bash
npm install pg
npm install --save-dev @types/pg  # If using TypeScript
```

## Basic Connection Pool Setup

Here's a comprehensive setup with proper timeout and error handling:

```javascript
const { Pool } = require('pg');

// Database configuration
const dbConfig = {
  // Connection settings
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME || 'your_database',
  user: process.env.DB_USER || 'your_username',
  password: process.env.DB_PASSWORD || 'your_password',

  // SSL configuration (important for production)
  ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false,

  // Connection pool settings
  max: 20,                    // Maximum number of clients in the pool
  min: 5,                     // Minimum number of clients in the pool
  idleTimeoutMillis: 30000,   // Close idle clients after 30 seconds
  connectionTimeoutMillis: 10000, // Return error after 10 seconds if connection could not be established
  maxUses: 7500,              // Close (and replace) a connection after it has been used this many times

  // Query timeout
  query_timeout: 30000,       // Query timeout in milliseconds
  statement_timeout: 30000,   // Statement timeout in milliseconds

  // Keep alive settings
  keepAlive: true,
  keepAliveInitialDelayMillis: 10000,
};

// Create the connection pool
const pool = new Pool(dbConfig);

// Error handling for the pool
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client', err);
  process.exit(-1);
});

pool.on('connect', (client) => {
  console.log('New client connected to the database');
});

pool.on('remove', (client) => {
  console.log('Client removed from pool');
});

module.exports = pool;
```

## Database Service Class

Here's a more structured approach using a service class:

```javascript
const { Pool } = require('pg');

class DatabaseService {
  constructor() {
    this.pool = new Pool({
      host: process.env.DB_HOST || 'localhost',
      port: process.env.DB_PORT || 5432,
      database: process.env.DB_NAME || 'your_database',
      user: process.env.DB_USER || 'your_username',
      password: process.env.DB_PASSWORD || 'your_password',
      ssl: process.env.NODE_ENV === 'production' ? { rejectUnauthorized: false } : false,

      // Pool configuration
      max: 20,
      min: 5,
      idleTimeoutMillis: 30000,
      connectionTimeoutMillis: 10000,
      maxUses: 7500,

      // Timeouts
      query_timeout: 30000,
      statement_timeout: 30000,

      // Keep alive
      keepAlive: true,
      keepAliveInitialDelayMillis: 10000,
    });

    this.setupEventHandlers();
  }

  setupEventHandlers() {
    this.pool.on('error', (err, client) => {
      console.error('Database pool error:', err);
      // Don't exit the process, just log the error
    });

    this.pool.on('connect', (client) => {
      console.log('Database client connected');
    });

    this.pool.on('acquire', (client) => {
      console.log('Client acquired from pool');
    });

    this.pool.on('remove', (client) => {
      console.log('Client removed from pool');
    });
  }

  // Execute a query with error handling
  async query(text, params = []) {
    const client = await this.pool.connect();

    try {
      const start = Date.now();
      const result = await client.query(text, params);
      const duration = Date.now() - start;

      console.log('Executed query', { text, duration, rows: result.rowCount });
      return result;
    } catch (error) {
      console.error('Database query error:', error);
      throw error;
    } finally {
      client.release();
    }
  }

  // Execute a transaction
  async transaction(callback) {
    const client = await this.pool.connect();

    try {
      await client.query('BEGIN');
      const result = await callback(client);
      await client.query('COMMIT');
      return result;
    } catch (error) {
      await client.query('ROLLBACK');
      console.error('Transaction error:', error);
      throw error;
    } finally {
      client.release();
    }
  }

  // Get pool status
  getPoolStatus() {
    return {
      totalCount: this.pool.totalCount,
      idleCount: this.pool.idleCount,
      waitingCount: this.pool.waitingCount,
    };
  }

  // Graceful shutdown
  async close() {
    console.log('Closing database pool...');
    await this.pool.end();
    console.log('Database pool closed');
  }
}

module.exports = new DatabaseService();
```

## Usage Examples

Here's how to use the database service:

```javascript
const db = require('./database-service');

// Simple query
async function getUsers() {
  try {
    const result = await db.query('SELECT * FROM users WHERE active = $1', [true]);
    return result.rows;
  } catch (error) {
    console.error('Error fetching users:', error);
    throw error;
  }
}

// Transaction example
async function createUserWithProfile(userData, profileData) {
  try {
    const result = await db.transaction(async (client) => {
      // Insert user
      const userResult = await client.query(
        'INSERT INTO users (name, email) VALUES ($1, $2) RETURNING id',
        [userData.name, userData.email]
      );

      const userId = userResult.rows[0].id;

      // Insert profile
      await client.query(
        'INSERT INTO profiles (user_id, bio, avatar) VALUES ($1, $2, $3)',
        [userId, profileData.bio, profileData.avatar]
      );

      return userId;
    });

    return result;
  } catch (error) {
    console.error('Error creating user with profile:', error);
    throw error;
  }
}

// Check pool health
function checkDatabaseHealth() {
  const status = db.getPoolStatus();
  console.log('Database pool status:', status);

  if (status.waitingCount > 5) {
    console.warn('High number of waiting connections');
  }
}
```

## Express.js Integration with Middleware

Here's how to integrate it with Express.js:

```javascript
const express = require('express');
const db = require('./database-service');

const app = express();

// Database health check middleware
app.use('/health', async (req, res) => {
  try {
    await db.query('SELECT 1');
    const status = db.getPoolStatus();
    res.json({ 
      status: 'healthy', 
      database: 'connected',
      pool: status 
    });
  } catch (error) {
    res.status(503).json({ 
      status: 'unhealthy', 
      database: 'disconnected',
      error: error.message 
    });
  }
});

// Graceful shutdown
process.on('SIGINT', async () => {
  console.log('Received SIGINT, shutting down gracefully...');

  try {
    await db.close();
    process.exit(0);
  } catch (error) {
    console.error('Error during shutdown:', error);
    process.exit(1);
  }
});

process.on('SIGTERM', async () => {
  console.log('Received SIGTERM, shutting down gracefully...');

  try {
    await db.close();
    process.exit(0);
  } catch (error) {
    console.error('Error during shutdown:', error);
    process.exit(1);
  }
});
```

## Environment Variables

Create a `.env` file for configuration:

```env
DB_HOST=localhost
DB_PORT=5432
DB_NAME=your_database
DB_USER=your_username
DB_PASSWORD=your_password
NODE_ENV=development
```

## Key Configuration Options Explained

- **max**: Maximum number of connections in the pool
- **min**: Minimum number of connections to maintain
- **idleTimeoutMillis**: How long a client can be idle before being closed
- **connectionTimeoutMillis**: How long to wait when connecting to the database
- **query_timeout**: Maximum time for a query to execute
- **statement_timeout**: PostgreSQL statement timeout
- **keepAlive**: Enables TCP keep-alive
- **maxUses**: Maximum number of times a connection can be reused

This setup provides robust connection pooling with proper error handling, timeouts, and graceful shutdown capabilities for production use.

