Use `pg` package pool:

```js
const { Pool } = require('pg')

const pool = new Pool({
  host: 'localhost',
  port: 5432,
  database: 'mydb',
  user: 'username',
  password: 'password',

  // Connection pool config
  max: 20,                    // max connections
  min: 2,                     // min idle connections
  idleTimeoutMillis: 30000,   // close idle after 30s
  connectionTimeoutMillis: 2000, // fail connect after 2s
  acquireTimeoutMillis: 60000,   // wait for connection 60s

  // Error handling
  allowExitOnIdle: true
})

// Error handler
pool.on('error', (err) => {
  console.error('Pool error:', err)
})

// Usage
async function query(text, params) {
  const client = await pool.connect()
  try {
    return await client.query(text, params)
  } finally {
    client.release()
  }
}

// Graceful shutdown
process.on('SIGINT', () => {
  pool.end(() => {
    console.log('Pool closed')
    process.exit(0)
  })
})
```

Key settings:
- `max`: keep under DB connection limit
- `connectionTimeoutMillis`: fail fast on DB down
- `acquireTimeoutMillis`: prevent infinite wait
- Always `client.release()` in finally block
- Handle pool errors + graceful shutdown

