```js
async function getUser(id) {
  return new Promise((resolve, reject) => {
    db.query('SELECT * FROM users WHERE id = ?', [id], function(err, rows) {
      if (err) return reject(err);
      if (!rows.length) return reject(new Error('Not found'));
      resolve(rows[0]);
    });
